#[inline]
fn parse_root_operation_types(p: &mut GraphqlParser) -> CompletedMarker {
    let m = p.start();
    p.expect(T!['{']);
    RootOperationTypeDefinitionList.parse_list(p);
    p.expect(T!['}']);
    m.complete(p, GRAPHQL_ROOT_OPERATION_TYPES)
